<?php
require_once __DIR__.'/config/config.php';require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';
$tur=$_GET['tur']??'takim_ligi';$sec=['takim_ligi'=>'Takım Ligleri','bireysel_lig'=>'Bireysel Bölge Ligleri','takim_turnuvasi'=>'Takım Turnuvaları','bireysel_turnuvasi'=>'Bireysel Turnuvalar'];if(!isset($sec[$tur]))$tur='takim_ligi';$sayfa_baslik='Karşılaşma Sonuçları';$aktif='sonuclar';require __DIR__.'/includes/header.php';
?>
<main class="main-content"><section class="page-heading"><span>SONUÇ MERKEZİ</span><h1>Karşılaşma Sonuçları</h1><p>Sonuç türünü seçerek tamamlanan karşılaşmaları takip edin.</p></section><nav class="sonuc-sekmeleri"><?php foreach($sec as $k=>$v): ?><a href="?tur=<?= $k ?>" class="<?= $tur===$k?'active':'' ?>"><?= $v ?></a><?php endforeach; ?></nav><section class="card"><?php if($tur==='takim_ligi'): $sonHafta=(int)$pdo->query("SELECT COALESCE(MAX(m.hafta),0) FROM maclar m JOIN gruplar g ON g.id=m.grup_id JOIN ligler l ON l.id=g.lig_id WHERE l.tur='takim' AND m.durum='oynandi'")->fetchColumn();$q=$pdo->prepare("SELECT m.*,a.takim_adi ev,b.takim_adi dep,g.grup_adi,l.lig_adi FROM maclar m JOIN takimlar a ON a.id=m.ev_sahibi_id JOIN takimlar b ON b.id=m.deplasman_id JOIN gruplar g ON g.id=m.grup_id JOIN ligler l ON l.id=g.lig_id WHERE l.tur='takim' AND m.durum='oynandi' AND m.hafta=? ORDER BY g.grup_adi,m.tarih,m.id");$q->execute([$sonHafta]);$maclar=$q->fetchAll(); ?><div class="card-head"><h2><?= $sonHafta ? $sonHafta.'. Hafta Sonuçları' : 'Son Hafta Sonuçları' ?></h2><span class="badge"><?= count($maclar) ?> karşılaşma</span></div><?php if(!$maclar): ?><p class="muted">Henüz tamamlanan Takım Ligi karşılaşması bulunmuyor.</p><?php else: ?><div class="match-list"><?php foreach($maclar as $x): ?><article><small><?= e($x['lig_adi'].' · '.$x['grup_adi']) ?></small><strong><a href="<?= BASE_URL ?>/mac.php?id=<?= (int)$x['id'] ?>"><?= e($x['ev']) ?> <span><?= (int)$x['ev_sahibi_set'] ?> - <?= (int)$x['deplasman_set'] ?></span> <?= e($x['dep']) ?></a></strong><a class="btn btn-sm" href="<?= BASE_URL ?>/mac.php?id=<?= (int)$x['id'] ?>">Detay</a></article><?php endforeach; ?></div><?php endif; elseif($tur==='bireysel_lig'): $q=$pdo->query("SELECT s.ad,s.soyad,k.toplam_puan,l.lig_adi,g.grup_adi FROM bireysel_lig_kayitlari k JOIN sporcular s ON s.id=k.sporcu_id JOIN ligler l ON l.id=k.lig_id JOIN gruplar g ON g.id=k.grup_id ORDER BY k.toplam_puan DESC,s.ad");?><div class="card-head"><h2>Bireysel Bölge Ligleri</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Lig / Grup</th><th>Sporcu</th><th>Puan</th></tr></thead><tbody><?php foreach($q as $x): ?><tr><td><?= e($x['lig_adi'].' · '.$x['grup_adi']) ?></td><td><?= e($x['ad'].' '.$x['soyad']) ?></td><td><?= (int)$x['toplam_puan'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">Turnuva sonuçları için ilgili turnuva kartını seçebilirsiniz.</p><?php endif; ?></section></main>
<?php require __DIR__.'/includes/sidebar.php';require __DIR__.'/includes/footer.php'; ?>
